  subgrtrl $p |- ( S SubGraph G ->
          ( F ( Trails ` S ) P -> F ( Trails ` G ) P ) ) $=
    ( csubgr wbr cwlks cfv ccnv wfun wa ctrls subgrwlk anim1d istrl 3imtr4g ) B
